def control(obs):
    global _pull
    h = obs['hitch_deg']
    ry = obs['rig']['trailer_rear'][1]
    if obs['status'] == 'JACKKNIFED' or abs(h) > 55:
        _pull = True
    if _pull and abs(h) < 15:
        _pull = False
    if _pull:
        return (0.0, 0.6, -23)
    steer = 1.0 * h + 12.0 * (ry + 0.2)
    steer = max(-34.0, min(34.0, steer))
    return (steer, -0.7, -23)

