ST = {'ph': 0, 't0': None}

def control(obs):
    t = obs.get('t', 0.0) or 0.0
    h = obs.get('hitch_deg', 0.0) or 0.0
    rig = obs.get('rig', {}) or {}
    rr = rig.get('trailer_rear', [0.0, 0.0]) or [0.0, 0.0]
    y = rr[1]
    mot = obs.get('motion', {}) or {}
    v = mot.get('v_mps', 0.0) or 0.0
    if ST['t0'] is None:
        ST['t0'] = t
    el = t - ST['t0']
    if ST['ph'] == 0:
        # forward pull, right steer swings rear right (away from left rail)
        if el > 6.0 or y < -0.6:
            ST['ph'] = 1
            ST['t0'] = t
        else:
            return (-22.0, 0.4, -41.0)
    if ST['ph'] == 1:
        # brake to standstill, then gear change to reverse
        if abs(v) < 0.02 and el > 0.5:
            ST['ph'] = 2
            ST['t0'] = t
        else:
            return (0.0, 0.0, -41.0)
    # reverse phase
    if abs(v) < 0.02 and el > 6.0:
        # reverse stalled (pinned again): pull forward once more
        ST['ph'] = 0
        ST['t0'] = t
        return (-22.0, 0.4, -41.0)
    steer = 3.0 * h + 4.0 * (y + 0.5)
    steer = max(-30.0, min(30.0, steer))
    return (steer, -0.15, -41.0)

