    dt = obs.get('dt', 0.1) or 0.1
    h = obs.get('hitch_deg', 0.0) or 0.0
    mot = obs.get('motion', {}) or {}
    v = mot.get('v_mps', 0.0) or 0.0
    hold = mot.get('hold_s', 0.0) or 0.0
    if ST['ph'] == 'fwd':
        if hold <= 0.01:
            ST['el'] += dt
        if ST['el'] > 3.0:
            ST['ph'] = 'brake'
            ST['el'] = 0.0
            return (0.0, 0.0, -41.0)
        return (-12.0, 0.2, -41.0)
    if ST['ph'] == 'brake':
        if abs(v) < 0.02 and hold <= 0.01:
            ST['ph'] = 'rev'
            ST['stall'] = 0.0
        return (0.0, 0.0, -41.0)
    if hold <= 0.01 and abs(v) < 0.02:
        ST['stall'] += dt
        if ST['stall'] > 2.5:
            ST['ph'] = 'fwd'
            ST['el'] = 0.0
            ST['stall'] = 0.0
            return (-12.0, 0.2, -41.0)
    else:
        ST['stall'] = 0.0
    steer = max(-25.0, min(25.0, 2.5 * (h + 10.0)))
    return (steer, -0.12, -41.0)

